large_16_count_distinct_days.sql:
select
    count(*) as distinct_days
from (
    select distinct date_trunc('day', time)
    from data_large
) t

db_overrides.postgres:
select count(*) as distinct_days
from (
    select distinct date_trunc('day', time) as d
    from data_large
    where metric_name = 'process_364'
) t

db_overrides.timescaledb:
select count(*) as distinct_days
from (
    select distinct time_bucket(INTERVAL '1 day', time) as d
    from data_large
    where metric_name = 'process_364'
) t

